import logging

import torch
import triton
import triton.language as tl

from flag_gems.utils import libentry
from flag_gems.utils.triton_lang_extension import program_id

logger = logging.getLogger(__name__)


@libentry()
@triton.jit
def eigvalsh_jacobi_kernel(
    A,
    W,
    N,
    batch_stride,
    w_stride,
    NSWEEP: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Cyclic (two-sided) Jacobi eigenvalue kernel for symmetric matrices.

    Each program computes the eigenvalues of one matrix in the batch. The whole
    N x N matrix is held in a BLOCK x BLOCK register tile. A sequence of Givens
    rotations J drives the off-diagonal entries to zero (A <- J^T A J), so the
    diagonal converges to the eigenvalues. Padding rows/cols (index >= N) are
    kept at zero and are never touched because every rotation plane (p, q) uses
    p, q < N.
    """
    pid = program_id(0)
    base = pid * batch_stride

    offs = tl.arange(0, BLOCK)
    rr = offs[:, None]
    cc = offs[None, :]
    mask = (rr < N) & (cc < N)

    # Load the symmetric matrix into a register tile.
    M = tl.load(A + base + rr * N + cc, mask=mask, other=0.0)

    for _ in range(NSWEEP):
        # Convergence check: stop sweeping once the matrix is essentially diagonal.
        # off = sum of squared off-diagonal entries.
        offsq = tl.sum(tl.where(rr != cc, M * M, 0.0))
        if offsq > 1e-30:
            for p in range(N):
                for q in range(p + 1, N):
                    # Extract the 2x2 pivot block scalars.
                    app = tl.sum(tl.where((rr == p) & (cc == p), M, 0.0))
                    aqq = tl.sum(tl.where((rr == q) & (cc == q), M, 0.0))
                    apq = tl.sum(tl.where((rr == p) & (cc == q), M, 0.0))

                    # Compute the Jacobi rotation (c, s) that zeros the (p, q) entry.
                    if apq * apq > 0.0:
                        tau = (aqq - app) / (2.0 * apq)
                        if tau >= 0.0:
                            t = 1.0 / (tau + tl.sqrt(1.0 + tau * tau))
                        else:
                            t = -1.0 / (-tau + tl.sqrt(1.0 + tau * tau))
                        c = 1.0 / tl.sqrt(1.0 + t * t)
                        s = t * c

                        # Right multiply: update columns p and q  (M <- M @ J).
                        colp = tl.sum(tl.where(cc == p, M, 0.0), axis=1)[:, None]
                        colq = tl.sum(tl.where(cc == q, M, 0.0), axis=1)[:, None]
                        new_colp = c * colp - s * colq
                        new_colq = s * colp + c * colq
                        M = tl.where(cc == p, new_colp, M)
                        M = tl.where(cc == q, new_colq, M)

                        # Left multiply: update rows p and q  (M <- J^T @ M).
                        rowp = tl.sum(tl.where(rr == p, M, 0.0), axis=0)[None, :]
                        rowq = tl.sum(tl.where(rr == q, M, 0.0), axis=0)[None, :]
                        new_rowp = c * rowp - s * rowq
                        new_rowq = s * rowp + c * rowq
                        M = tl.where(rr == p, new_rowp, M)
                        M = tl.where(rr == q, new_rowq, M)

    # The diagonal now holds the eigenvalues (unsorted).
    diag = tl.sum(tl.where(rr == cc, M, 0.0), axis=1)
    tl.store(W + pid * w_stride + offs, diag, mask=offs < N)


def linalg_eigvalsh(A, UPLO="L"):
    logger.debug("GEMS LINALG_EIGVALSH")
    assert A.dtype in (
        torch.float32,
        torch.float64,
    ), "linalg_eigvalsh only supports float32 and float64"

    shape = A.shape
    if A.dim() < 2:
        raise ValueError("A must be at least 2D")

    n = shape[-1]
    m = shape[-2]
    if m != n:
        raise ValueError("A must be batches of square matrices")

    batch_shape = shape[:-2]
    batch_size = 1
    for d in batch_shape:
        batch_size *= d

    A_view = A.reshape(batch_size, n, n)

    # Build a full symmetric matrix from the requested triangle so that the
    # kernel input matches torch's UPLO semantics (only that triangle is read).
    if UPLO == "U":
        upper = torch.triu(A_view)
        A_sym = upper + torch.triu(A_view, diagonal=1).transpose(-2, -1).conj()
    else:  # "L"
        lower = torch.tril(A_view)
        A_sym = lower + torch.tril(A_view, diagonal=-1).transpose(-2, -1).conj()

    A_sym = A_sym.contiguous()

    W = torch.empty((batch_size, n), dtype=A.dtype, device=A.device)

    if n == 0:
        return W.reshape(batch_shape + (0,))
    if n == 1:
        # 1x1 matrix: the single element is the eigenvalue.
        return A_sym.reshape(batch_size, 1).reshape(batch_shape + (1,))

    block = triton.next_power_of_2(n)
    nsweep = 20

    grid = (batch_size,)
    with torch.no_grad():
        eigvalsh_jacobi_kernel[grid](
            A_sym,
            W,
            n,
            A_sym.stride(0),
            W.stride(0),
            NSWEEP=nsweep,
            BLOCK=block,
        )

    # torch.linalg.eigvalsh returns eigenvalues in ascending order.
    W, _ = torch.sort(W, dim=-1)
    return W.reshape(batch_shape + (n,))
